      detailed: { en: 'Name This Surah is named Al-Fatihah because of its subject matter. Fatihah is that which opens a subject or a book or any other thing. In other words, Al-Fatihah is a sort of preface. Period of Revelation Surah Al-Fatihah is one of the very earliest Revelations to the Holy Prophet. As a matter of fact, we learn from authentic traditions that it was the first complete Surah that was revealed to Muhammad (Allah\'s peace be upon him). Before this, only a few miscellaneous verses were revealed which ', ar: 'سورة الفاتحة أم القرآن ومثانيه السبع، نزلت بمكة المكرمة وهي أولى سور القرآن الكريم. تضمّنت ثلاثة محاور: التحميد والثناء على الله (الآيات 1-4)، وإقرار التوحيد والعبادة (الآية 5)، والتضرع بطلب الهداية (الآيات 6-7). رسول الله صلى الله عليه وسلم قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب. وهي دعاء يرفعه العبد لربه فيجيبه الله بسائر القرآن كما في الحديث القدسي.' },
