      detailed: { en: 'Name This Surah takes its\' name from verse 112 in which the word mai\'dah occurs. Like the names of many other surahs, this name has no special relation to the subject of the Surah but has been used merely as a symbol to distinguish it from other surahs. Period of Revelation The theme of this Surah indicates, and traditions support it, that it was revealed after the treaty of Hudaibiyah at the end of 6 A. H. or at the beginning of 7 A. H. That is why it deals with those problems that arose from t', ar: 'سورة المائدة ختمت التشريع الإسلامي، وتناولت الحلال والحرام والعهود والعقود وقصة الحواريين.' },
