      detailed: { en: 'Name The Surah takes its name from v. 35 in which mention has been made of Prophet Ibrahim (Abraham). But it does not mean that it contains the life story of Prophet Abraham. The name is merely a symbol lid the names of many other surahs, i.e., the Surah in which Abraham\'s mention has been made. Period of Revelation It appears from the tone of the Surah that it belongs to that group of the Surahs which were revealed during the last stage of the Makkan period. For instance, v. 13 ("The disbelieve', ar: 'سورة إبراهيم تصوّر دعوة إبراهيم عليه السلام وشكره لله، وتتحدث عن نعم الله ومآل الكافرين.' },
