      detailed: { en: 'Name The word Fatir of the first very verse is the title given to this Surah, which simply means that it is a Surah in which the word Fatir has occurred. The other name is Al Malaika , which also occurs in the first verse . Period of Revelation The internal evidence of the style shows that the period of the revelation of this Surah is probably the middle Makkan period, and especially that part of it, when antagonism had grown quite strong and every sort of mischief was being adopted to frustrate', ar: 'سورة فاطر تسبّح بحمد الله خالق الملائكة ورسالات الأنبياء ومُقدّر الأرزاق والآجال.' },
