      detailed: { en: 'Name It is derived from the sentence idh andhara qauma-hu bil Ahqaf-i of verse 21 . Period of Revelation It is determined by an historical event that has been mentioned in vv. 29-32 . This incident of the visit of the jinn and their going back after listening to the Qur\'an had occurred, according to agreed traditions of the Hadith and biographical literature, at the time when the Holy Prophet had halted at Makkah during his return journey from Ta\'if to Makkah. And according to all authentic hist', ar: 'سورة الأحقاف تروي كيف أسلمت الجن بعد سماعهم القرآن وتُذكّر بعاقبة قوم عاد في الأحقاف.' },
