      detailed: { en: 'Name The Surah takes its title from the sentence, Wa anzalna\' l-hadida , of verse 25 . Period of Revelation This is unanimously a Madani Surah, and a study of its subject matter shows that it was probably sent down some time during the interval between the Battle of Uhud and the Truce of Hudaibiyah. This was the time when the tiny Islamic State of Madinah had been hemmed in by the disbelievers and the handful of the ill equipped Muslims were entrenched against the combined power of entire Arabia', ar: 'سورة الحديد تدعو إلى الإنفاق في سبيل الله وتُؤصّل الزهد في الدنيا وتُبشّر المتصدقين.' },
