      detailed: { en: 'Name The Surah derives its name from the sentence yuqatiluna fi sabil-i- hlsaff-an of verse 4 ; thereby implying that it is a Surah in which the word saff occurred. Period of Revelation It could not be known from any reliable tradition, but a study of its subject-matter shows that this Surah probably was sent down in the period closely following the Battle of Uhud, for by reading between the lines perceives a clear description of the conditions that prevailed in that period. Theme and Subject Ma', ar: 'سورة الصف تحثّ على نصرة دين الله وتذكر موقف موسى وعيسى من قومهما وتُبشّر بانتصار الإسلام.' },
