      short: { en: 'It is derived from the sentence idha nudiya-lis-salat-imin-yaum-il- Jumu\'ati of verse 9. Although in this Surah injunctions about the Friday congregational Prayer also have been given, yet \'Jumu\'ah\' is not the title of its subject-matter as a whole, but this name too, like the names of other Surahs, is only a symbolic title.', ar: 'سورة الجمعة تُبيّن فريضة صلاة الجمعة وتُحذّر من التقصير في الاستجابة لها.' },
      detailed: { en: 'Name It is derived from the sentence idha nudiya-lis-salat-imin-yaum-il- Jumu\'ati of verse 9 . Although in this Surah injunctions about the Friday congregational Prayer also have been given, yet " Jumu\'ah " is not the title of its subject-matter as a whole, but this name too, like the names of other Surahs, is only a symbolic title. Period of Revelation The period of the revelation of the first section ( vv. 1-8 ) is A. H. 7, and probably it was sent down, on the occasion of the conquest of Khai', ar: 'سورة الجمعة تُبيّن فريضة صلاة الجمعة وتُحذّر من التقصير في الاستجابة لها.' },
